fn find_max_in_prefix(v: &[i32], end: usize) -> (i32, usize) {
    // Precondition: end < v.len()
    // Find max value and an index where it occurs in v[0..=end]
    let mut max_val = v[0];
    let mut max_idx = 0;
    for i in 1..=end {
        if v[i] > max_val {
            max_val = v[i];
            max_idx = i;
        }
    }
    (max_val, max_idx)
}

fn find_min_in_suffix(v: &[i32], start: usize) -> (i32, usize) {
    // Precondition: start < v.len()
    // Find min value and an index where it occurs in v[start..]
    let mut min_val = v[start];
    let mut min_idx = start;
    for i in (start + 1)..v.len() {
        if v[i] < min_val {
            min_val = v[i];
            min_idx = i;
        }
    }
    (min_val, min_idx)
}

fn barrier(v: &[i32], p: usize) -> bool {
    // Precondition: v.len() > 0 and p < v.len()
    // If p is the last index, there are no elements after p => vacuously true
    if p + 1 >= v.len() {
        return true;
    }
    // Get max in prefix up to p
    let (max_prefix, _) = find_max_in_prefix(v, p);
    // Get min in suffix starting at p + 1
    let (min_suffix, _) = find_min_in_suffix(v, p + 1);
    // Strict barrier condition: max_prefix < min_suffix
    max_prefix < min_suffix
}